import numpy as np


def attention(Q, K, V):
    Q, K, V = (np.asarray(a, dtype=float) for a in (Q, K, V))
    S = Q @ K.T
    S = S - S.max(axis=-1, keepdims=True)
    A = np.exp(S)
    A = A / A.sum(axis=-1, keepdims=True)
    return A @ V


def attention_shapes(n_q, n_k, d, d_v):
    return {'Q': [n_q, d], 'K': [n_k, d], 'V': [n_k, d_v], 'scores': [n_q, n_k], 'out': [n_q, d_v]}

