import numpy as np

g = np.random.default_rng(4)
Xq, Xk = g.standard_normal((3, 4)), g.standard_normal((5, 4))
P = {'WQ': 0.5 * g.standard_normal((4, 4)), 'WK': 0.5 * g.standard_normal((4, 4)), 'WV': 0.5 * g.standard_normal((4, 2))}


def fd_err(Xq, Xk, params, eps=1e-6):
    _, grads = attention_autograd(Xq, Xk, params)
    worst, scale = 0.0, 1e-12
    for key, val in params.items():
        for i in np.ndindex(val.shape):
            up = {k: v.copy() for k, v in params.items()}
            dn = {k: v.copy() for k, v in params.items()}
            up[key][i] += eps
            dn[key][i] -= eps
            num = (attention_autograd(Xq, Xk, up)[0].sum() - attention_autograd(Xq, Xk, dn)[0].sum()) / (2 * eps)
            worst = max(worst, abs(num - grads[key][i]))
            scale = max(scale, abs(num), abs(grads[key][i]))
    return worst / scale
